import sys

SMALL = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten', 'eleven', 'twelve',
         'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen']
TENS = ['', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety']

def below100(x):
    if x < 20:
        return SMALL[x]
    return TENS[x // 10] + (' ' + SMALL[x % 10] if x % 10 else '')

def below1000(x):
    parts = []
    if x >= 100:
        parts.append(SMALL[x // 100] + ' hundred')
        x %= 100
    if x:
        parts.append(below100(x))
    return ' '.join(parts)

def main():
    n = int(sys.stdin.read().split()[0])
    if n == 0:
        print('zero')
        return
    parts = []
    for value, name in ((n // 10**7, 'crore'), (n // 10**5 % 100, 'lakh'), (n // 1000 % 100, 'thousand')):
        if value:
            parts.append(below100(value) + ' ' + name)
    if n % 1000:
        parts.append(below1000(n % 1000))
    print(' '.join(parts))

main()

